import sys
from collections import defaultdict, deque

def main():
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    index += 1
    s = list(map(int, input[index:index + n]))
    index += n
    m = int(input[index])
    index += 1
    pipes = []
    for _ in range(m):
        x = int(input[index]) - 1
        y = int(input[index + 1]) - 1
        pipes.append((x, y))
        index += 2

    graph = defaultdict(list)
    for i, (x, y) in enumerate(pipes):
        graph[x].append((y, i))
        graph[y].append((x, i))

    visited = [False] * n
    flow = [0] * m

    def bfs(start):
        queue = deque([(start, 0)])
        visited[start] = True
        parent = [-1] * n
        edge_id = [-1] * n
        while queue:
            u, _ = queue.popleft()
            for v, i in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    edge_id[v] = i
                    if v == start:
                        return parent, edge_id
                    queue.append((v, 0))
        return None, None

    for i in range(n):
        if not visited[i]:
            parent, edge_id = bfs(i)
            if parent is None:
                print("Impossible")
                return

    for i in range(n):
        if not visited[i]:
            stack = [(i, 0)]
            while stack:
                u, excess = stack.pop()
                for v, idx in graph[u]:
                    if parent[v] == u:
                        if edge_id[v] != -1:
                            if flow[edge_id[v]] == 0:
                                flow[edge_id[v]] = min(excess, -s[v])
                            stack.append((v, excess - flow[edge_id[v]]))
                        else:
                            stack.append((v, excess + flow[edge_id[u]]))
                    elif parent[u] == v:
                        if edge_id[u] != -1:
                            if flow[edge_id[u]] == 0:
                                flow[edge_id[u]] = min(-excess, s[u])
                            stack.append((v, excess + flow[edge_id[u]]))
                        else:
                            stack.append((v, excess - flow[edge_id[v]]))

    for i in range(m):
        x, y = pipes[i]
        if flow[i] == 0:
            flow[i] = min(s[x], -s[y])

    if any(s[i] != 0 for i in range(n)):
        print("Impossible")
        return

    print("Possible")
    for f in flow:
        print(f)

main()
